import matplotlib.pyplot as plt
import numpy as np
import imageio.v2 as imageio
import os

# 1. Load the trajectory data generated by your new C++ code
try:
    data = np.loadtxt('trajectory_poses.csv', delimiter=',', skiprows=1)
    if data.ndim == 1:
        data = np.array([data])
except Exception as e:
    print(f"Error loading trajectory_poses.csv: Make sure to run your new C++ code first! Details: {e}")
    exit(1)

# Extract columns
steps = data[:, 0]
xs = data[:, 1]
ys = data[:, 2]
zs = data[:, 3]
yaws = data[:, 6]

# 2. Set up the figure window
fig = plt.figure(figsize=(9, 6))
ax = fig.add_subplot(projection='3d')

frames = []
temp_filename = 'temp_traj_frame.png'

print("Rendering motion animation frames...")

# 3. Loop through each time step to show actual motion
for i in range(len(data)):
    ax.clear()
    
    # Draw the path trail up to the current step
    ax.plot(xs[:i+1], ys[:i+1], zs[:i+1], color='gray', linestyle='--', linewidth=1.5, label='Path Traveled')
    
    # Plot the robot's current position marker
    x, y, z, yaw = xs[i], ys[i], zs[i], yaws[i]
    ax.scatter(x, y, z, color='red', s=140, label='Robot Position')
    
    # Draw a heading arrow showing which way it's facing at this step
    dx = np.cos(yaw) * 0.6
    dy = np.sin(yaw) * 0.6
    ax.quiver(x, y, z, dx, dy, 0.0, color='blue', normalize=True, linewidth=2, label='Heading')
    
    # Keep the graph boundaries locked so the scene stays stable during animation
    ax.set_xlim([np.min(xs) - 0.5, np.max(xs) + 0.5])
    ax.set_ylim([np.min(ys) - 1.0, np.max(ys) + 1.0])
    ax.set_zlim([0, np.max(zs) + 1.0])
    
    ax.set_xlabel('X Axis')
    ax.set_ylabel('Y Axis')
    ax.set_zlabel('Z Axis')
    ax.set_title(f'Simple3D - Robot Motion Trajectory (Step {i+1}/{len(data)})')
    ax.legend(loc='upper left')
    
    # Save frame
    plt.savefig(temp_filename, dpi=100, format='png')
    frames.append(imageio.imread(temp_filename))

# Clean up temp image file
if os.path.exists(temp_filename):
    os.remove(temp_filename)

# 4. Save frames as a motion GIF
output_gif = 'robot_trajectory.gif'
imageio.mimsave(output_gif, frames, fps=8)
print(f"Success! Motion animation saved as '{output_gif}' in your project folder.")